"overlayGradient\":\"linear-gradient(90deg, var(\\u002d\\u002dglobal-palette1) 12%, var(\\u002d\\u002dglobal-palette2) 100%)\",\"padding\":[0,0,0,0],\"kbVersion\":2} -->\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_64d275-30\",\"kbVersion\":2,\"className\":\"inner-column-1\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_64d275-30 inner-column-1\"><div class=\"kt-inside-inner-col\"><!-- wp:kadence/rowlayout {\"uniqueID\":\"21_415932-9e\",\"columns\":1,\"colLayout\":\"equal\",\"bgImg\":\"https://lasnotes.com/wp-content/uploads/2025/02/sass_bg-min.png\",\"verticalAlignment\":\"middle\",\"bottomSep\":\"mtns\",\"bottomSepColor\":\"palette9\",\"bottomSepHeight\":120,\"inheritMaxWidth\":true,\"padding\":[120,25,100,25],\"kbVersion\":2} -->\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_ddf6d5-aa\",\"kbVersion\":2,\"className\":\"inner-column-1\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_ddf6d5-aa inner-column-1\"><div class=\"kt-inside-inner-col\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|theme-palette9\"}}},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"700\"}},\"textColor\":\"theme-palette9\",\"fontSize\":\"xxlarge\"} -->\n<h1 class=\"wp-block-heading has-text-align-center has-theme-palette-9-color has-text-color has-link-color has-xxlarge-font-size\" style=\"font-style:normal;font-weight:700\">Free open source cross-platform standalone<br>Quick Notes Application</h1>\n<!-- /wp:heading -->\n\n<!-- wp:kadence/advancedheading {\"level\":3,\"uniqueID\":\"21_6b45af-7c\",\"align\":\"center\",\"color\":\"#f7fafc\",\"fontWeight\":\"normal\",\"margin\":[1,null,1.5,null],\"marginType\":\"em\",\"markFontWeight\":\"regular\",\"markBorder\":\"\",\"markBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"tabletMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"mobileMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"colorClass\":\"\",\"enableTextShadow\":true,\"textShadow\":[{\"enable\":true,\"color\":\"rgba(0, 0, 0, 0.2)\",\"blur\":1,\"hOffset\":1,\"vOffset\":1}],\"htmlTag\":\"p\",\"fontSize\":[24,null,null]} -->\n<p class=\"kt-adv-heading21_6b45af-7c wp-block-kadence-advancedheading\" data-kb-block=\"kb-adv-heading21_6b45af-7c\">Full control. Works offline. Not a service. No vendor lock</p>\n<!-- /wp:kadence/advancedheading -->\n\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_a5a820-a3\",\"kbVersion\":2} -->\n<div class=\"wp-block-kadence-column kadence-column21_a5a820-a3\"><div class=\"kt-inside-inner-col\"><!-- wp:image {\"id\":63,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"align\":\"center\",\"style\":{\"border\":{\"color\":\"var(\\u002d\\u002dglobal-palette3)\",\"radius\":\"30px\"}}} -->\n<figure class=\"wp-block-image aligncenter size-large has-custom-border\"><img src=\"https://lasnotes.com/wp-content/uploads/2025/02/screenshot-windows-1024x630.jpg\" alt=\"\" class=\"has-border-color wp-image-63\" style=\"border-color:var(--global-palette3);border-radius:30px\"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:kadence/column --></div></div>\n<!-- /wp:kadence/column -->\n\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_7973e9-de\",\"height\":[0,\"\",\"\"],\"kbVersion\":2,\"className\":\"inner-column-1\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_7973e9-de inner-column-1\"><div class=\"kt-inside-inner-col\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|theme-palette8\"}}}},\"textColor\":\"theme-palette8\",\"fontSize\":\"larger\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-theme-palette-8-color has-text-color has-link-color has-larger-font-size\">Why Las Notes?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:kadence/advancedheading {\"level\":3,\"uniqueID\":\"21_1bf5ab-43\",\"align\":\"center\",\"color\":\"palette8\",\"fontWeight\":\"normal\",\"margin\":[1,null,1.5,null],\"marginType\":\"em\",\"markFontWeight\":\"regular\",\"markBorder\":\"\",\"markBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"tabletMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"mobileMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"colorClass\":\"theme-palette8\",\"enableTextShadow\":true,\"textShadow\":[{\"enable\":true,\"color\":\"rgba(0, 0, 0, 0.2)\",\"blur\":1,\"hOffset\":1,\"vOffset\":1}],\"htmlTag\":\"p\",\"fontSize\":[\"md\",\"\",\"\"]} -->\n<p class=\"kt-adv-heading21_1bf5ab-43 wp-block-kadence-advancedheading has-theme-palette-8-color has-text-color\" data-kb-block=\"kb-adv-heading21_1bf5ab-43\">Las Notes is a free open source standalone cross-platform Quick Notes editor.<br>All your thoughts are kept as a linear feed of small notes like in social networks.<br>Just create a new DB file and start adding new quick notes.<br>Then you can quickly search them by tags or by keywords in global search.</p>\n<!-- /wp:kadence/advancedheading --></div></div>\n<!-- /wp:kadence/column -->\n<!-- /wp:kadence/rowlayout --></div></div>\n<!-- /wp:kadence/column -->\n<!-- /wp:kadence/rowlayout -->\n\n<!-- wp:kadence/advancedbtn {\"uniqueID\":\"21_a06e21-44\"} -->\n<div class=\"wp-block-kadence-advancedbtn kb-buttons-wrap kb-btns21_a06e21-44\"><!-- wp:kadence/singlebtn {\"uniqueID\":\"21_8c7254-86\",\"text\":\"D