out --></div></div>\n<!-- /wp:kadence/column -->\n\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_4bbecf-12\",\"kbVersion\":2} -->\n<div class=\"wp-block-kadence-column kadence-column21_4bbecf-12\"><div class=\"kt-inside-inner-col\"><!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_d04998-d1\",\"kbVersion\":2} -->\n<div class=\"wp-block-kadence-column kadence-column21_d04998-d1\"><div class=\"kt-inside-inner-col\"><!-- wp:kadence/advancedbtn {\"uniqueID\":\"21_cf4de9-b7\"} -->\n<div class=\"wp-block-kadence-advancedbtn kb-buttons-wrap kb-btns21_cf4de9-b7\"><!-- wp:kadence/singlebtn {\"uniqueID\":\"21_c1eb8b-49\",\"text\":\"Download for Mac\",\"padding\":[12,32,12,32],\"color\":\"#ffffff\",\"background\":\"palette2\",\"colorHover\":\"palette9\",\"backgroundHover\":\"palette3\",\"borderStyle\":[{\"top\":[\"rgba(85, 85, 85, 0)\",\"\",0],\"right\":[\"rgba(85, 85, 85, 0)\",\"\",0],\"bottom\":[\"rgba(85, 85, 85, 0)\",\"\",0],\"left\":[\"rgba(85, 85, 85, 0)\",\"\",0],\"unit\":\"px\"}],\"borderHoverStyle\":[{\"top\":[\"rgba(68, 68, 68, 0)\",\"\",\"\"],\"right\":[\"rgba(68, 68, 68, 0)\",\"\",\"\"],\"bottom\":[\"rgba(68, 68, 68, 0)\",\"\",\"\"],\"left\":[\"rgba(68, 68, 68, 0)\",\"\",\"\"],\"unit\":\"px\"}],\"borderRadius\":[50,50,50,50],\"icon\":\"fe_arrowRight\",\"typography\":[{\"size\":[20,\"\",\"\"],\"sizeType\":\"px\",\"lineHeight\":[\"\",\"\",\"\"],\"lineType\":\"\",\"letterSpacing\":[\"\",\"\",\"\"],\"letterType\":\"px\",\"family\":\"\",\"google\":false,\"style\":\"normal\",\"weight\":\"regular\",\"variant\":\"\",\"subset\":\"\",\"textTransform\":\"\",\"loadGoogle\":true}]} /-->\n\n<!-- wp:kadence/singlebtn {\"uniqueID\":\"21_22baaf-d5\",\"text\":\"Download for Windows\",\"padding\":[12,32,12,32],\"color\":\"#ffffff\",\"background\":\"palette2\",\"colorHover\":\"palette9\",\"backgroundHover\":\"palette3\",\"borderStyle\":[{\"top\":[\"rgba(85, 85, 85, 0)\",\"\",0],\"right\":[\"rgba(85, 85, 85, 0)\",\"\",0],\"bottom\":[\"rgba(85, 85, 85, 0)\",\"\",0],\"left\":[\"rgba(85, 85, 85, 0)\",\"\",0],\"unit\":\"px\"}],\"borderHoverStyle\":[{\"top\":[\"rgba(68, 68, 68, 0)\",\"\",\"\"],\"right\":[\"rgba(68, 68, 68, 0)\",\"\",\"\"],\"bottom\":[\"rgba(68, 68, 68, 0)\",\"\",\"\"],\"left\":[\"rgba(68, 68, 68, 0)\",\"\",\"\"],\"unit\":\"px\"}],\"borderRadius\":[50,50,50,50],\"icon\":\"fe_arrowRight\",\"typography\":[{\"size\":[20,\"\",\"\"],\"sizeType\":\"px\",\"lineHeight\":[\"\",\"\",\"\"],\"lineType\":\"\",\"letterSpacing\":[\"\",\"\",\"\"],\"letterType\":\"px\",\"family\":\"\",\"google\":false,\"style\":\"normal\",\"weight\":\"regular\",\"variant\":\"\",\"subset\":\"\",\"textTransform\":\"\",\"loadGoogle\":true}]} /--></div>\n<!-- /wp:kadence/advancedbtn --></div></div>\n<!-- /wp:kadence/column --></div></div>\n<!-- /wp:kadence/column -->\n<!-- /wp:kadence/rowlayout -->\n\n<!-- wp:kadence/rowlayout {\"uniqueID\":\"21_6bc31f-c3\",\"columns\":1,\"colLayout\":\"equal\",\"maxWidth\":1400,\"padding\":[80,25,80,25],\"kbVersion\":2} -->\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_ba86a9-8e\",\"kbVersion\":2,\"className\":\"inner-column-1\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_ba86a9-8e inner-column-1\"><div class=\"kt-inside-inner-col\"><!-- wp:kadence/rowlayout {\"uniqueID\":\"21_15b74f-37\",\"columnGutter\":\"wider\",\"colLayout\":\"equal\",\"minHeight\":450,\"verticalAlignment\":\"middle\",\"padding\":[24,\"\",40,\"\"],\"kbVersion\":2} -->\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_340a56-78\",\"kbVersion\":2,\"className\":\"inner-column-1\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_340a56-78 inner-column-1\"><div class=\"kt-inside-inner-col\"><!-- wp:image {\"id\":120,\"sizeSlug\":\"large\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"https://lasnotes.com/wp-content/uploads/2025/02/analytics-dash-1024x596-1.png\" alt=\"\" class=\"wp-image-120\"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:kadence/column -->\n\n<!-- wp:kadence/column {\"id\":2,\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_407799-13\",\"padding\":[0,30,0,50],\"tabletPadding\":[0,30,0,0],\"mobilePadding\":[0,10,0,10],\"kbVersion\":2,\"className\":\"inner-column-2\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_407799-13 inner-column-2\"><div class=\"kt-inside-inner-col\"><!-- wp:kadence/advancedheading {\"uniqueID\":\"21_89d715-8d\",\"align\":\"left\",\"fontWeight\":\"normal\",\"margin\":[\"\",null,\"\",null],\"markFontWeight\":\"regular\",\"markBorder\":\"\",\"markBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"tabletMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"mobileMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"colorClass\":\"\",\"fontSize\":[30,null,null]} -->\n<h2 class=\"kt-adv-heading21_89d715-8d wp-block-kadence-advancedheading\" data-kb-block=\"kb-adv-heading21_89d715-8d\">No vendor lock. What does it mean?</h2>\n<!-- /wp:kadence/advancedheading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":20}}} -->\n<p style=\"font-size:20px\">Most popular note taking apps are implemented \"as a service\". On the one hand, all notes are stored in a cloud, and it\'s simpler to synchronize them. On the other hand, if the service goes down (yes, it happens from time to time), you will lose everything. Also the service provider may change their billing policy and force you to pay more and more, just for your pieces of text.<br>With Las Notes you will control the full lifecycle of your notes stored in DB files. You can archive them, back them up, share, copy-paste, etc.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:kadence/column -->\n<!-- /wp:kadence/rowlayout -->\n\n<!-- wp:kadence/rowlayout {\"uniqueID\":\"21_7496ac-e6\",\"collapseOrder\":\"right-to-left\",\"columnGutter\":\"wider\",\"colLayout\":\"equal\",\"currentTab\":\"mobile\",\"minHeight\":450,\"verticalAlignment\":\"middle\",\"padding\":[40,\"\",40,\"\"],\"kbVersion\":2} -->\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_442f85-bc\",\"padding\":[0,50,0,30],\"tabletPadding\":[0,0,0,30],\"mobilePadding\":[0,10,0,10],\"kbVersion\":2,\"className\":\"inner-column-1\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_442f85-bc inner-column-1\"><div class=\"kt-inside-inner-col\"><!-- wp:kadence/advancedheading {\"uniqueID\":\"21_ba0990-9f\",\"align\":\"left\",\"fontWeight\":\"normal\",\"margin\":[\"\",null,\"\",null],\"markFontWeight\":\"regular\",\"markBorder\":\"\",\"markBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"tabletMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"mobileMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"colorClass\":\"\",\"fontSize\":[30,null,null]} -->\n<h2 class=\"kt-adv-heading21_ba0990-9f wp-block-kadence-advancedheading\" data-kb-block=\"kb-adv-heading21_ba0990-9f\">What about synchronization?</h2>\n<!-- /wp:kadence/advancedheading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":20}}} -->\n<p style=\"font-size:20px\">Since Las Notes keeps your notes in simple DB files, you can use any synchronization tool of your choice.<br>○ Cloud platforms (Dropbox, iCloud, One Drive, Google Cloud, pCloud, etc.)<br>○ Version control systems (Github, Gitlab, BitBucket, etc.)<br>○ Enterprise resource management solutions (MS Active Directory, etc.)<br>○ Distributed storage tools (Samba, etc.)<br>○ Simple Unix sync tools, like \"rsync\"<br>○ Uploads to your dedicating storage via FTP or web-server<br>○ Share as attachments to email, popular messengers and social networks</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":20}}} -->\n<p style=\"font-size:20px\"></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:kadence/column -->\n\n<!-- wp:kadence/column {\"id\":2,\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_a46842-1d\",\"kbVersion\":2,\"className\":\"inner-column-2\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_a46842-1d inner-column-2\"><div class=\"kt-inside-inner-col\"><!-- wp:image {\"id\":119,\"sizeSlug\":\"large\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"https://lasnotes.com/wp-content/uploads/2025/02/layout.png\" alt=\"\" class=\"wp-image-119\"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:kadence/column -->\n<!-- /wp:kadence/rowlayout -->\n\n<!-- wp:kadence/rowlayout {\"uniqueID\":\"21_0d9eee-a4\",\"columnGutter\":\"wider\",\"colLayout\":\"equal\",\"minHeight\":450,\"verticalAlignment\":\"middle\",\"padding\":[40,\"\",40,\"\"],\"kbVersion\":2} -->\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_dc2601-f1\",\"kbVersion\":2,\"className\":\"inner-column-1\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_dc2601-f1 inner-column-1\"><div class=\"kt-inside-inner-col\"><!-- wp:image {\"id\":126,\"sizeSlug\":\"large\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"https://lasnotes.com/wp-content/uploads/2025/02/devices-icon.png\" alt=\"\" class=\"wp-image-126\"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:kadence/column -->\n\n<!-- wp:kadence/column {\"id\":2,\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_35e6ff-34\",\"padding\":[0,30,0,50],\"tabletPadding\":[0,30,0,0],\"mobilePadding\":[0,10,0,10],\"kbVersion\":2,\"className\":\"inner-column-2\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_35e6ff-34 inner-column-2\"><div class=\"kt-inside-inner-col\"><!-- wp:kadence/advancedheading {\"uniqueID\":\"21_299f29-42\",\"align\":\"left\",\"fontWeight\":\"normal\",\"margin\":[\"\",null,\"\",null],\"markFontWeight\":\"regular\",\"markBorder\":\"\",\"markBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"tabletMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"mobileMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"colorClass\":\"\",\"fontSize\":[30,null,null]} -->\n<h2 class=\"kt-adv-heading21_299f29-42 wp-block-kadence-advancedheading\" data-kb-block=\"kb-adv-heading21_299f29-42\">What about backup?</h2>\n<!-- /wp:kadence/advancedheading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":20}}} -->\n<p style=\"font-size:20px\">All notes are stored in DB files. Backing them up is as simple as you backup your local documents or photos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:kadence/advancedheading {\"uniqueID\":\"21_1e11ca-88\",\"align\":\"left\",\"fontWeight\":\"normal\",\"margin\":[\"\",null,\"\",null],\"markFontWeight\":\"regular\",\"markBorder\":\"\",\"markBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"tabletMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"mobileMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"colorClass\":\"\",\"fontSize\":[30,null,null]} -->\n<h2 class=\"kt-adv-heading21_1e11ca-88 wp-block-kadence-advancedheading\" data-kb-block=\"kb-adv-heading21_1e11ca-88\">How secure is this?</h2>\n<!-- /wp:kadence/advancedheading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":20}}} -->\n<p style=\"font-size:20px\">We don\'t store your data. You\'re the one in charge for your notes if you want to utilize any 3d party synchronization tool.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:kadence/column -->\n<!-- /wp:kadence/rowlayout --></div></div>\n<!-- /wp:kadence/column -->\n\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_b982c0-1f\",\"kbVersion\":2,\"className\":\"inner-column-1\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_b982c0-1f inner-column-1\"><div class=\"kt-inside-inner-col\"><!-- wp:kadence/rowlayout {\"uniqueID\":\"21_cf0757-74\",\"collapseOrder\":\"right-to-left\",\"columnGutter\":\"wider\",\"colLayout\":\"equal\",\"currentTab\":\"mobile\",\"minHeight\":450,\"verticalAlignment\":\"middle\",\"padding\":[40,\"\",40,\"\"],\"kbVersion\":2} -->\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_9f22cb-5b\",\"padding\":[0,50,0,30],\"tabletPadding\":[0,0,0,30],\"mobilePadding\":[0,10,0,10],\"kbVersion\":2,\"className\":\"inner-column-1\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_9f22cb-5b inner-column-1\"><div class=\"kt-inside-inner-col\"><!-- wp:kadence/advancedheading {\"uniqueID\":\"21_f5cdd6-fc\",\"align\":\"left\",\"fontWeight\":\"normal\",\"margin\":[\"\",null,\"\",null],\"markFontWeight\":\"regular\",\"markBorder\":\"\",\"markBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"tabletMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"mobileMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"colorClass\":\"\",\"fontSize\":[30,null,null]} -->\n<h2 class=\"kt-adv-heading21_f5cdd6-fc wp-block-kadence-advancedheading\" data-kb-block=\"kb-adv-heading21_f5cdd6-fc\">Force majeure?</h2>\n<!-- /wp:kadence/advancedheading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":20}}} -->\n<p style=\"font-size:20px\">In case of emergency, recall that your thoughts are kept in local SQLite DB files. Open these files with any SQL editor, and you can find and access all your notes easily.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:kadence/advancedheading {\"uniqueID\":\"21_5ff400-b5\",\"align\":\"left\",\"fontWeight\":\"normal\",\"margin\":[\"\",null,\"\",null],\"markFontWeight\":\"regular\",\"markBorder\":\"\",\"markBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"tabletMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"mobileMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"colorClass\":\"\",\"fontSize\":[30,null,null]} -->\n<h2 class=\"kt-adv-heading21_5ff400-b5 wp-block-kadence-advancedheading\" data-kb-block=\"kb-adv-heading21_5ff400-b5\">Commercial usage?</h2>\n<!-- /wp:kadence/advancedheading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":20}}} -->\n<p style=\"font-size:20px\">Yes, you can use it for personal, enterprise and government purposes. No data is shared and even no network connection is being established.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:kadence/column -->\n\n<!-- wp:kadence/column {\"id\":2,\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_462cda-6e\",\"kbVersion\":2,\"className\":\"inner-column-2\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_462cda-6e inner-column-2\"><div class=\"kt-inside-inner-col\"><!-- wp:image {\"id\":119,\"sizeSlug\":\"large\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"https://lasnotes.com/wp-content/uploads/2025/02/layout.png\" alt=\"\" class=\"wp-image-119\"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:kadence/column -->\n<!-- /wp:kadence/rowlayout -->\n\n<!-- wp:kadence/rowlayout {\"uniqueID\":\"21_eb1a72-52\",\"columnGutter\":\"wider\",\"colLayout\":\"equal\",\"minHeight\":450,\"verticalAlignment\":\"middle\",\"padding\":[40,\"\",40,\"\"],\"kbVersion\":2} -->\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_38a147-ea\",\"kbVersion\":2,\"className\":\"inner-column-1\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_38a147-ea inner-column-1\"><div class=\"kt-inside-inner-col\"><!-- wp:image {\"id\":126,\"sizeSlug\":\"large\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"https://lasnotes.com/wp-content/uploads/2025/02/devices-icon.png\" alt=\"\" class=\"wp-image-126\"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:kadence/column -->\n\n<!-- wp:kadence/column {\"id\":2,\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_a52a3d-3f\",\"padding\":[0,30,0,50],\"tabletPadding\":[0,30,0,0],\"mobilePadding\":[0,10,0,10],\"kbVersion\":2,\"className\":\"inner-column-2\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_a52a3d-3f inner-column-2\"><div class=\"kt-inside-inner-col\"><!-- wp:kadence/advancedheading {\"uniqueID\":\"21_ffa122-bf\",\"align\":\"left\",\"fontWeight\":\"normal\",\"margin\":[\"\",null,\"\",null],\"markFontWeight\":\"regular\",\"markBorder\":\"\",\"markBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"tabletMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"mobileMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"colorClass\":\"\",\"fontSize\":[30,null,null]} -->\n<h2 class=\"kt-adv-heading21_ffa122-bf wp-block-kadence-advancedheading\" data-kb-block=\"kb-adv-heading21_ffa122-bf\">Compatibility?</h2>\n<!-- /wp:kadence/advancedheading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":20}}} -->\n<p style=\"font-size:20px\">○ All your DB files are compatible between all the platforms in Las Notes. You can create the DB file on Mac and it should work the same way on Windows.<br>○ Unofficial apps may add extra incompatible features to your DB files that may not be supported by official Las Notes app.<br>○ Different versions of Las Notes follow the backward compatibility policy. All DB files created in older versions of Las Notes should work with newer versions of the app. Newer features may not work with older versions of the app.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":20}}} -->\n<p style=\"font-size:20px\"></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:kadence/column -->\n<!-- /wp:kadence/rowlayout --></div></div>\n<!-- /wp:kadence/column -->\n<!-- /wp:kadence/rowlayout -->\n\n<!-- wp:kadence/rowlayout {\"uniqueID\":\"21_2004c3-07\",\"columns\":1,\"colLayout\":\"equal\",\"bgColor\":\"palette1\",\"topSep\":\"mtns\",\"topSepColor\":\"palette9\",\"topSepHeight\":120,\"bottomSep\":\"mtns\",\"bottomSepColor\":\"palette9\",\"bottomSepHeight\":120,\"bgColorClass\":\"theme-palette1\",\"padding\":[200,25,200,25],\"kbVersion\":2} -->\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_5fc2c3-77\",\"kbVersion\":2,\"className\":\"inner-column-1\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_5fc2c3-77 inner-column-1\"><div class=\"kt-inside-inner-col\"><!-- wp:kadence/testimonials {\"uniqueID\":\"21_addeed-3f\",\"gap\":[30,\"\",\"\"],\"containerMaxWidth\":600,\"containerBorder\":\"#eeeeee\",\"container