atform no-service<br>Quick Notes Application</h1>\n<!-- /wp:heading -->\n\n<!-- wp:kadence/advancedheading {\"level\":3,\"uniqueID\":\"21_c8b961-35\",\"align\":\"center\",\"color\":\"#f7fafc\",\"fontWeight\":\"normal\",\"margin\":[1,null,1.5,null],\"marginType\":\"em\",\"markFontWeight\":\"regular\",\"markBorder\":\"\",\"markBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"tabletMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"mobileMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"colorClass\":\"\",\"enableTextShadow\":true,\"textShadow\":[{\"enable\":true,\"color\":\"rgba(0, 0, 0, 0.2)\",\"blur\":1,\"hOffset\":1,\"vOffset\":1}],\"htmlTag\":\"p\",\"fontSize\":[20,null,null]} -->\n<p class=\"kt-adv-heading21_c8b961-35 wp-block-kadence-advancedheading\" data-kb-block=\"kb-adv-heading21_c8b961-35\">Full control. Works offline. No vendor lock.</p>\n<!-- /wp:kadence/advancedheading --></div></div>\n<!-- /wp:kadence/column -->\n\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_17c162-0b\",\"height\":[0,\"\",\"\"],\"kbVersion\":2,\"className\":\"inner-column-1\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_17c162-0b inner-column-1\"><div class=\"kt-inside-inner-col\"><!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Why Las Notes?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:kadence/advancedheading {\"level\":3,\"uniqueID\":\"21_cc9960-f4\",\"align\":\"center\",\"color\":\"#272323\",\"fontWeight\":\"normal\",\"margin\":[1,null,1.5,null],\"marginType\":\"em\",\"markFontWeight\":\"regular\",\"markBorder\":\"\",\"markBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"tabletMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"mobileMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"colorClass\":\"\",\"enableTextShadow\":true,\"textShadow\":[{\"enable\":true,\"color\":\"rgba(0, 0, 0, 0.2)\",\"blur\":1,\"hOffset\":1,\"vOffset\":1}],\"htmlTag\":\"p\",\"fontSize\":[\"md\",\"\",\"\"]} -->\n<p class=\"kt-adv-heading21_cc9960-f4 wp-block-kadence-advancedheading\" data-kb-block=\"kb-adv-heading21_cc9960-f4\">Las Notes is an indefinite linear feed of quick notes with Global Search support.<br>Stop creating complex trees of notes with heavy multi-category structure.<br>Just start Las Notes, create a new DB file and start adding new quick notes.<br>Then you can search them by tags or by keywords in Global Search.</p>\n<!-- /wp:kadence/advancedheading --></div></div>\n<!-- /wp:kadence/column -->\n\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_4d5a96-c2\",\"kbVersion\":2} -->\n<div class=\"wp-block-kadence-column kadence-column21_4d5a96-c2\"><div class=\"kt-inside-inner-col\"><!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_4188ea-35\",\"kbVersion\":2} -->\n<div class=\"wp-block-kadence-column kadence-column21_4188ea-35\"><div class=\"kt-inside-inner-col\"><!-- wp:kadence/advancedbtn {\"uniqueID\":\"21_8ea219-8d\"} -->\n<div class=\"wp-block-kadence-advancedbtn kb-buttons-wrap kb-btns21_8ea219-8d\"><!-- wp:kadence/singlebtn {\"uniqueID\":\"21_9a2f1d-66\",\"text\":\"Download for Mac\",\"padding\":[12,32,12,32],\"color\":\"#ffffff\",\"background\":\"palette2\",\"colorHover\":\"palette9\",\"backgroundHover\":\"palette3\",\"borderStyle\":[{\"top\":[\"rgba(85, 85, 85, 0)\",\"\",0],\"right\":[\"rgba(85, 85, 85, 0)\",\"\",0],\"bottom\":[\"rgb