"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"colorClass\":\"\",\"enableTextShadow\":true,\"textShadow\":[{\"enable\":true,\"color\":\"rgba(0, 0, 0, 0.2)\",\"blur\":1,\"hOffset\":1,\"vOffset\":1}],\"htmlTag\":\"p\",\"fontSize\":[24,null,null]} -->\n<p class=\"kt-adv-heading21_c8b961-35 wp-block-kadence-advancedheading\" data-kb-block=\"kb-adv-heading21_c8b961-35\">Full control. Works offline. No vendor lock.</p>\n<!-- /wp:kadence/advancedheading --></div></div>\n<!-- /wp:kadence/column -->\n\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_17c162-0b\",\"height\":[0,\"\",\"\"],\"kbVersion\":2,\"className\":\"inner-column-1\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_17c162-0b inner-column-1\"><div class=\"kt-inside-inner-col\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|theme-palette8\"}}}},\"textColor\":\"theme-palette8\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-theme-palette-8-color has-text-color has-link-color\">Why Las Notes?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:kadence/advancedheading {\"level\":3,\"uniqueID\":\"21_cc9960-f4\",\"align\":\"center\",\"color\":\"palette8\",\"fontWeight\":\"normal\",\"margin\":[1,null,1.5,null],\"marginType\":\"em\",\"markFontWeight\":\"regular\",\"markBorder\":\"\",\"markBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"tabletMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"mobileMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"colorClass\":\"theme-palette8\",\"enableTextShadow\":true,\"textShadow\":[{\"enable\":true,\"color\":\"rgba(0, 0, 0, 0.2)\",\"blur\":1,\"hOffset\":1,\"