n<!-- /wp:kadence/infobox --></div></div>\n<!-- /wp:kadence/column -->\n\n<!-- wp:kadence/column {\"id\":2,\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_6094f3-64\",\"kbVersion\":2,\"className\":\"inner-column-2\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_6094f3-64 inner-column-2\"><div class=\"kt-inside-inner-col\"><!-- wp:kadence/infobox {\"uniqueID\":\"21_38f392-0b\",\"containerBackground\":\"palette9\",\"containerBackgroundOpacity\":1,\"containerHoverBackground\":\"palette9\",\"containerHoverBackgroundOpacity\":1,\"containerPadding\":[30,30,30,30],\"mediaIcon\":[{\"icon\":\"fe_checkCircle\",\"size\":40,\"width\":1.5,\"title\":\"\",\"color\":\"#ffffff\",\"hoverColor\":\"#ffffff\",\"hoverAnimation\":\"none\",\"flipIcon\":\"\"}],\"mediaStyle\":[{\"background\":\"palette1\",\"hoverBackground\":\"palette1\",\"border\":\"#444444\",\"hoverBorder\":\"#444444\",\"borderRadius\":100,\"borderWidth\":[0,0,0,0],\"padding\":[15,15,15,15],\"margin\":[0,0,20,0]}],\"titleColor\":\"palette3\",\"titleHoverColor\":\"palette3\",\"titleFont\":[{\"level\":2,\"size\":[24,\"\",\"\"],\"sizeType\":\"px\",\"lineHeight\":[\"\",\"\",\"\"],\"lineType\":\"px\",\"letterSpacing\":\"\",\"textTransform\":\"\",\"family\":\"\",\"google\":false,\"style\":\"normal\",\"weight\":\"regular\",\"variant\":\"\",\"subset\":\"\",\"loadGoogle\":true,\"padding\":[0,0,0,0],\"paddingControl\":\"linked\",\"margin\":[5,0,10,0],\"marginControl\":\"individual\"}],\"textColor\":\"palette5\",\"textHoverColor\":\"palette5\",\"textFont\":[{\"size\":[16,\"\",\"\"],\"sizeType\":\"px\",\"lineHeight\":[\"\",\"\",\"\"],\"lineType\":\"px\",\"letterSpacing\":\"\",\"family\":\"\",\"google\":false,\"style\":\"normal\",\"weight\":\"regular\",\"variant\":\"\",\"subset\":\"\",\"loadGoogle\":true}],\"learnMoreStyles\":[{\"size\":[\"\",\"\",\"\"],\"sizeType\":\"px\",\"lineHeight\":[\"\",\"\",\"\"],\"lineType\":\"px\",\"letterSpacing\":\"\",\"family\":\"\",\"google\":\"\",\"style\":\"\",\"weight\":\"\",\"var