ayout --></div></div>\n<!-- /wp:kadence/column -->\n<!-- /wp:kadence/rowlayout -->\n\n<!-- wp:kadence/rowlayout {\"uniqueID\":\"21_765d35-43\",\"columns\":3,\"colLayout\":\"equal\",\"bgColor\":\"palette2\",\"topSep\":\"\",\"bgColorClass\":\"theme-palette2\",\"kbVersion\":2} -->\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_fe0d94-81\",\"kbVersion\":2} -->\n<div class=\"wp-block-kadence-column kadence-column21_fe0d94-81\"><div class=\"kt-inside-inner-col\"><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|theme-palette8\"}}}},\"textColor\":\"theme-palette8\"} -->\n<p class=\"has-text-align-center has-theme-palette-8-color has-text-color has-link-color\">Copyright © 2025. Artem Mitrakov</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:kadence/column -->\n\n<!-- wp:kadence/column {\"id\":2,\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_a15236-24\",\"kbVersion\":2} -->\n<div class=\"wp-block-kadence-column kadence-column21_a15236-24\"><div class=\"kt-inside-inner-col\"><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|theme-palette8\"}}}},\"textColor\":\"theme-palette8\"} -->\n<p class=\"has-text-align-center has-theme-palette-8-color has-text-color has-link-color\">Support: <a href=\"mailto:support@lasnotes.com\" target=\"_blank\" rel=\"noreferrer noopener\">support@lasnotes.com</a><br>Source code: <a href=\"https://github.com/mitrakov/las-notes\" target=\"_blank\" rel=\"noreferrer noopener\">Github page</a></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:kadence/column -->\n\n<!-- wp:kadence/column {\"id\":3,\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_da6616-b8\",\"kbVersion\":2} -->\n<div class=\"wp-block-kadence-column kadence-column21_da6616-b8\"><div class=\"kt-inside-inner-col\"><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:p