":\"px\",\"family\":\"\",\"google\":false,\"style\":\"normal\",\"weight\":\"regular\",\"variant\":\"\",\"subset\":\"\",\"textTransform\":\"\",\"loadGoogle\":true}],\"displayShadow\":true,\"shadow\":[{\"color\":\"#000000\",\"opacity\":0.2,\"spread\":0,\"blur\":2,\"hOffset\":3,\"vOffset\":3,\"inset\":false}]} /--></div>\n<!-- /wp:kadence/advancedbtn -->\n\n<!-- wp:kadence/rowlayout {\"uniqueID\":\"21_9218dc-2b\",\"columns\":1,\"colLayout\":\"equal\",\"bgColor\":\"palette1\",\"topSep\":\"mtns\",\"topSepColor\":\"palette9\",\"topSepHeight\":120,\"bottomSep\":\"mtns\",\"bottomSepColor\":\"palette9\",\"bottomSepHeight\":120,\"bgColorClass\":\"theme-palette1\",\"padding\":[200,25,200,25],\"kbVersion\":2} -->\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_b8fe44-11\",\"kbVersion\":2,\"className\":\"inner-column-1\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_b8fe44-11 inner-column-1\"><div class=\"kt-inside-inner-col\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|theme-palette8\"}}}},\"textColor\":\"theme-palette8\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-theme-palette-8-color has-text-color has-link-color\">Markdown support</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|theme-palette7\"}}}},\"textColor\":\"theme-palette7\"} -->\n<p class=\"has-text-align-center has-theme-palette-7-color has-text-color has-link-color\">Please check the <a href=\"https://docs.github.com/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax\" target=\"_blank\" rel=\"noreferrer noopener\">Github guide</a> to follow the Markdown syntax in Las Notes.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:kadence/column -->\n<!-- /wp:kadence/rowlayout -->\n\n<!-- wp:kadence/rowlayout {\"uniqueID\":\"21