ant\":\"\",\"subset\":\"\",\"loadGoogle\":true,\"padding\":[4,8,4,8],\"paddingControl\":\"individual\",\"margin\":[10,0,10,0],\"marginControl\":\"individual\",\"color\":\"\",\"background\":\"transparent\",\"border\":\"#555555\",\"borderRadius\":0,\"borderWidth\":[0,0,0,0],\"borderControl\":\"linked\",\"colorHover\":\"#ffffff\",\"backgroundHover\":\"#444444\",\"borderHover\":\"#444444\",\"hoverEffect\":\"revealBorder\"}],\"displayShadow\":true,\"shadow\":[{\"color\":\"#000000\",\"opacity\":0.03,\"spread\":0,\"blur\":30,\"hOffset\":0,\"vOffset\":0}],\"shadowHover\":[{\"color\":\"#000000\",\"opacity\":0.07,\"spread\":0,\"blur\":40,\"hOffset\":0,\"vOffset\":0}],\"borderStyle\":[{\"top\":[\"#eeeeee\",\"\",\"\"],\"right\":[\"#eeeeee\",\"\",\"\"],\"bottom\":[\"#eeeeee\",\"\",\"\"],\"left\":[\"#eeeeee\",\"\",\"\"],\"unit\":\"px\"}],\"borderHoverStyle\":[{\"top\":[\"#eeeeee\",\"\",\"\"],\"right\":[\"#eeeeee\",\"\",\"\"],\"bottom\":[\"#eeeeee\",\"\",\"\"],\"left\":[\"#eeeeee\",\"\",\"\"],\"unit\":\"px\"}],\"borderRadius\":[10,10,10,10],\"kbVersion\":2} -->\n<div class=\"wp-block-kadence-infobox kt-info-box21_38f392-0b\"><span class=\"kt-blocks-info-box-link-wrap info-box-link kt-blocks-info-box-media-align-top kt-info-halign-center\"><div class=\"kt-blocks-info-box-media-container\"><div class=\"kt-blocks-info-box-media kt-info-media-animate-none\"><div class=\"kadence-info-box-icon-container kt-info-icon-animate-none\"><div class=\"kadence-info-box-icon-inner-container\"><span data-name=\"fa_github\" data-class=\"kt-info-svg-icon\" class=\"kadence-dynamic-icon\"></span></div></div></div></div><div class=\"kt-infobox-textcontent\"><h2 class=\"kt-blocks-info-box-title\">Open source</h2><p class=\"kt-blocks-info-box-text\">Las Notes is completely open source. You can find source code for Mac and Windows on our Github page.<br><br></p></div></span></div>\n<!-- /wp:kadence/infobox --></div></div>\n<!-- /wp:kadence/column -->\n\n<!-- wp:kadence/column {\"id\":3,\"borderWidth\":[\"