latform standalone<br>Quick Notes Application</h1>\n<!-- /wp:heading -->\n\n<!-- wp:kadence/advancedheading {\"level\":3,\"uniqueID\":\"21_aaaef7-b1\",\"align\":\"center\",\"color\":\"#f7fafc\",\"fontWeight\":\"normal\",\"margin\":[1,null,1.5,null],\"marginType\":\"em\",\"markFontWeight\":\"regular\",\"markBorder\":\"\",\"markBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"tabletMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"mobileMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"colorClass\":\"\",\"enableTextShadow\":true,\"textShadow\":[{\"enable\":true,\"color\":\"rgba(0, 0, 0, 0.2)\",\"blur\":1,\"hOffset\":1,\"vOffset\":1}],\"htmlTag\":\"p\",\"fontSize\":[24,null,null]} -->\n<p class=\"kt-adv-heading21_aaaef7-b1 wp-block-kadence-advancedheading\" data-kb-block=\"kb-adv-heading21_aaaef7-b1\">Full control. Works offline. Not a service. No vendor lock</p>\n<!-- /wp:kadence/advancedheading -->\n\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_b55f99-79\",\"kbVersion\":2} -->\n<div class=\"wp-block-kadence-column kadence-column21_b55f99-79\"><div class=\"kt-inside-inner-col\"><!-- wp:image {\"id\":63,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"align\":\"center\",\"style\":{\"border\":{\"color\":\"var(\\u002d\\u002dglobal-palette3)\",\"radius\":\"30px\"}}} -->\n<figure class=\"wp-block-image aligncenter size-large has-custom-border\"><img src=\"https://lasnotes.com/wp-content/uploads/2025/02/screenshot-windows-1024x630.jpg\" alt=\"\" class=\"has-border-color wp-image-63\" style=\"border-color:var(--global-palette3);border-radius:30px\"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:kadence/column --></div></div>\n<!-- /wp:kadence/column -->\n\n<!-- wp:kadence/column {\"borderWidth\":[\"\",\"\",\"\",\"\"],\"uniqueID\":\"21_83de0e-54\",\"height\":[0,\"\",\"\"],\"kbVersion\":2,\"className\":\"inner-column-1\"} -->\n<div class=\"wp-block-kadence-column kadence-column21_83de0e-54 inner-column-1\"><div class=\"kt-inside-inner-col\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|theme-palette8\"}}}},\"textColor\":\"theme-palette8\",\"fontSize\":\"larger\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-theme-palette-8-color has-text-color has-link-color has-larger-font-size\">Why Las Notes?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:kadence/advancedheading {\"level\":3,\"uniqueID\":\"21_07f210-7d\",\"align\":\"center\",\"color\":\"palette8\",\"fontWeight\":\"normal\",\"margin\":[1,null,1.5,null],\"marginType\":\"em\",\"markFontWeight\":\"regular\",\"markBorder\":\"\",\"markBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"tabletMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"mobileMarkBorderStyles\":[{\"top\":[null,\"\",\"\"],\"right\":[null,\"\",\"\"],\"bottom\":[null,\"\",\"\"],\"left\":[null,\"\",\"\"],\"unit\":\"px\"}],\"colorClass\":\"theme-palette8\",\"enableTextShadow\":true,\"textShadow\":[{\"enable\":true,\"color\":\"rgba(0, 0, 0, 0.2)\",\"blur\":1,\"hOffset\":1,\"vOffset\":1}],\"htmlTag\":\"p\",\"fontSize\":[\"md\",\"\",\"\"]} -->\n<p class=\"kt-adv-heading21_07f210-7d wp-block-kadence-advancedheading has-theme-palette-8-color has-text-color\" data-kb-block=\"kb-adv-heading21_07f210-7d\">Las Notes is a linear feed of quick notes.<br>Just create a new DB file and start adding new quick notes.<br>Then you can search them by tags or by keywords in Global Search.</p>\n<!-- /wp:kadence/advancedheading --></div></div>\n<!-- /wp:kaden